# owner: platform
"""Find the stretches of opening hours nobody covers."""

from typing import Iterable, List
from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans

def _check_inside(spans: List[Span], hours: Span):
    for span in spans:
        if span.start < hours.start or span.end > hours.end:
            text = format_span(span)
            raise ValueError(f"outside hours: {text}")

def _uncovered(spans: List[Span], hours: Span):
    cursor = hours.start
    for span in merge_spans(spans):
        if span.start > cursor:
            yield Span(cursor, span.start)
        cursor = span.end
    if cursor < hours.end:
        yield Span(cursor, hours.end)

def _label(gap: Span) -> str:
    return f"gap {format_span(gap)} ({gap.minutes} min)"

# ---
def find_gaps(worked: Iterable[Span], hours: Span):
    """Label each gap; ValueError if outside hours."""
    worked = list(worked)
    _check_inside(worked, hours)
    gaps = _uncovered(worked, hours)
    return [_label(gap) for gap in gaps]
